BEGIN;

DELETE FROM public.compute_insight_gpu_price_detail_daily
WHERE source_label = 'price_mining'
  AND price_date = '2026-11-17'
  AND provider_id IN ('bentaus','cirrascale','coregpu','cyfuture','daytona','digitalocean','gpubank','hotaisle','impossible-cloud','microsoft-azure','openrelay','oracle-cloud','runcrate','runpod','tensorwave','vultr')
  AND gpu_model_code IN ('MI300X','MI325X','MI355X');


COMMIT;
